	// 保存结果必须指向原请求的批次：另一批次的结果即使配方与投料数量
	// 完全相同，也不能顶替。
	if result.BatchNo != batchNo {
		return fmt.Errorf("%w: 关闭请求 %q（批次 %q）保存结果的批次编号为 %q，不能用另一批次的结果顶替",
			ErrCorruptData, reqNo, batchNo, result.BatchNo)
