package release

import (
	"encoding/json"
	"fmt"
	"time"
)

const (
	opCreateBatch = "createBatch"
	opUpdateDraft = "updateDraftBatch"
	opStartBatch  = "startBatch"
	opCloseBatch  = "closeBatch"
	opAddFeeding  = "addFeeding"
)

type createBatchPayload struct {
	BatchNo  string
	RecipeNo string
	Version  string
	Portions int
}

type updateDraftPayload struct {
	BatchNo  string
	RecipeNo string // 留空表示不改配方
	Version  string // 与 RecipeNo 同时给出
	Portions int    // 0 表示不改份数
}

type startBatchPayload struct {
	BatchNo string
}

type closeBatchPayload struct {
	BatchNo string
}

type addFeedingPayload struct {
	BatchNo    string
	MaterialNo string
	Grams      string
	Time       time.Time
	Registrar  string
}

// CreateBatch 创建批次。
// 批次使用独立批次编号，选择已登记的配方版本和计划份数（必须为正整数）。
// 新批次为草稿；批次编号重复、配方版本不存在或数量不合法时返回具体原因且不保留数据。
func (s *Store) CreateBatch(reqNo, batchNo, recipeNo, version string, portions int) (*BatchView, error) {
	payload := createBatchPayload{BatchNo: batchNo, RecipeNo: recipeNo, Version: version, Portions: portions}
	var out BatchView
	err := s.write(reqNo, opCreateBatch, payload, func(st *persistedState) (json.RawMessage, error) {
		if batchNo == "" {
			return nil, fmt.Errorf("%w: 批次编号不能为空", ErrInvalidInput)
		}
		if portions <= 0 {
			return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, portions)
		}
		if findBatch(st, batchNo) != nil {
			return nil, fmt.Errorf("%w: 批次 %q 已存在", ErrDuplicateBatch, batchNo)
		}
		r := findRecipe(st, recipeNo, version)
		if r == nil {
			return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, recipeNo, version)
		}
		// 份数为正整数还要满足：按该配方版本逐物料计算的应投量都能精确
		// 表示且不超上限。这是本次提交的输入规则，不满足按 ErrInvalidInput
		// 拒绝，不能落盘成之后读取时才发现损坏的批次。
		if err := validatePlanForRecipe(r, portions); err != nil {
			return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err)
		}
		b := &batchRecord{
			BatchNo:         batchNo,
			RecipeNo:        recipeNo,
			RecipeVersion:   version,
			PlannedPortions: portions,
			Status:          StatusDraft,
		}
		view, err := buildBatchView(b, r)
		if err != nil {
			return nil, err
		}
		raw, err := json.Marshal(view)
		if err != nil {
			return nil, err
		}
		st.Batches = append(st.Batches, b)
		return raw, nil
	}, &out)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// UpdateDraftBatch 调整草稿批次的计划份数或改选配方版本。
// newRecipeNo/newVersion 都留空表示不改配方；newPortions 传 0 表示不改份数。
// 只有草稿状态可以调整；开始执行后两者固定。
func (s *Store) UpdateDraftBatch(reqNo, batchNo, newRecipeNo, newVersion string, newPortions int) (*BatchView, error) {
	payload := updateDraftPayload{BatchNo: batchNo, RecipeNo: newRecipeNo, Version: newVersion, Portions: newPortions}
	var out BatchView
	err := s.write(reqNo, opUpdateDraft, payload, func(st *persistedState) (json.RawMessage, error) {
		b := findBatch(st, batchNo)
		if b == nil {
			return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
		}
		if b.Status != StatusDraft {
			return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有草稿可以调整", ErrInvalidState, batchNo, b.Status)
		}
		// 先解析调整后的最终份数与配方版本（份数传 0 表示沿用原份数，
		// 配方编号与版本号都留空表示沿用原版本），全部解析并校验通过
		// 后才改动记录，保证失败时不留下半调整状态。
		finalPortions := b.PlannedPortions
		if newPortions != 0 {
			if newPortions <= 0 {
				return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, newPortions)
			}
			finalPortions = newPortions
		}
		finalRecipeNo, finalVersion := b.RecipeNo, b.RecipeVersion
		if newRecipeNo != "" || newVersion != "" {
			if newRecipeNo == "" || newVersion == "" {
				return nil, fmt.Errorf("%w: 改选配方版本时必须同时给出配方编号和版本号", ErrInvalidInput)
			}
			finalRecipeNo, finalVersion = newRecipeNo, newVersion
		}
		r := findRecipe(st, finalRecipeNo, finalVersion)
		if r == nil {
			return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, finalRecipeNo, finalVersion)
		}
		// 最终计划同样必须满足：每种物料按最终版本、最终份数计算的应投量
		// 都能精确表示且不超上限；沿用合法原计划（无变化调整）时该校验
		// 在读取时已经通过，这里再统一校验一次。这是本次提交的输入规则，
		// 不满足按 ErrInvalidInput 整体拒绝，不落盘份数或配方的半成品。
		if err := validatePlanForRecipe(r, finalPortions); err != nil {
			return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err)
		}
		b.PlannedPortions = finalPortions
		b.RecipeNo = finalRecipeNo
		b.RecipeVersion = finalVersion
		view, err := buildBatchView(b, r)
		if err != nil {
			return nil, err
		}
		raw, err := json.Marshal(view)
		if err != nil {
			return nil, err
		}
		return raw, nil
	}, &out)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// StartBatch 开始执行批次：草稿 → 执行中。
// 开始后计划份数与配方版本固定，只有执行中的批次可以关闭。
func (s *Store) StartBatch(reqNo, batchNo string) (*BatchView, error) {
	payload := startBatchPayload{BatchNo: batchNo}
	var out BatchView
	err := s.write(reqNo, opStartBatch, payload, func(st *persistedState) (json.RawMessage, error) {
		return transitionBatchStatus(st, batchNo, StatusDraft, StatusExecuting, "只有草稿可以开始执行")
	}, &out)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// CloseBatch 关闭批次：执行中 → 已关闭。
// 关闭表示确认已有投料，不要求数量已经吻合；
// 关闭后不能追加投料，也不能重新打开。
func (s *Store) CloseBatch(reqNo, batchNo string) (*BatchView, error) {
	payload := closeBatchPayload{BatchNo: batchNo}
	var out BatchView
	err := s.write(reqNo, opCloseBatch, payload, func(st *persistedState) (json.RawMessage, error) {
		return transitionBatchStatus(st, batchNo, StatusExecuting, StatusClosed, "只有执行中的批次可以关闭")
	}, &out)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// transitionBatchStatus 是批次状态变更（开始执行、关闭）的统一实现：
// 找到批次后要求当前状态为 from，否则按 ErrInvalidState 拒绝（批次不存在
// 按 ErrNotFound 拒绝，两种情况下状态与投料都不变）；通过后将状态改为 to，
// 并按变更后的记录构造返回视图。rule 说明该变更的准入规则，用于状态不符时
// 的错误信息。配方版本、计划份数与已有投料均保持原样。
func transitionBatchStatus(st *persistedState, batchNo string, from, to BatchStatus, rule string) (json.RawMessage, error) {
	b := findBatch(st, batchNo)
	if b == nil {
		return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
	}
	if b.Status != from {
		return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，%s", ErrInvalidState, batchNo, b.Status, rule)
	}
	b.Status = to
	r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
	if r == nil {
		return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
			ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
	}
	view, err := buildBatchView(b, r)
	if err != nil {
		return nil, err
	}
	raw, err := json.Marshal(view)
	if err != nil {
		return nil, err
	}
	return raw, nil
}

// AddFeeding 向执行中的批次追加一次投料。
// 投料包含物料编号、克数（正数、最多三位小数）、投料时间和登记人；
// 物料必须属于该批次绑定的配方版本。允许实际投料不足或超过应投量；
// 已登记的投料不能修改或删除，关闭后也不能追加。
// 同一批次内每种物料的累计实投量（仅按该物料统计）上限为
// 9223372036854775.807 克，本次投料后恰好等于上限仍允许，超过则返回
// ErrInvalidInput 且不保存本次投料。
// 投料按成功登记的先后顺序编号，不按投料时间重排。
func (s *Store) AddFeeding(reqNo, batchNo, materialNo, grams string, t time.Time, registrar string) (*FeedingView, error) {
	payload := addFeedingPayload{
		BatchNo:    batchNo,
		MaterialNo: materialNo,
		Grams:      grams,
		Time:       t,
		Registrar:  registrar,
	}
	var out FeedingView
	err := s.write(reqNo, opAddFeeding, payload, func(st *persistedState) (json.RawMessage, error) {
		if materialNo == "" {
			return nil, fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
		}
		if registrar == "" {
			return nil, fmt.Errorf("%w: 登记人不能为空", ErrInvalidInput)
		}
		milli, err := parseGrams(grams)
		if err != nil {
			return nil, fmt.Errorf("%w: 物料 %q 的克数: %v", ErrInvalidInput, materialNo, err)
		}
		b := findBatch(st, batchNo)
		if b == nil {
			return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
		}
		if b.Status != StatusExecuting {
			return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以投料", ErrInvalidState, batchNo, b.Status)
		}
		r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
		if r == nil {
			return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
				ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
		}
		belongs := false
		for _, m := range r.Materials {
			if m.MaterialNo == materialNo {
				belongs = true
				break
			}
		}
		if !belongs {
			return nil, fmt.Errorf("%w: 物料 %q 不在配方 %q 版本 %q 中",
				ErrMaterialNotInRecipe, materialNo, r.RecipeNo, r.Version)
		}

		// 上限按物料分别判断：只累计该物料已登记的投料，
		// 其他物料的投料量不参与，也不互相抵消。
		acc := newFeedingAccumulator()
		fit := true
		for _, f := range b.Feedings {
			if !acc.add(f.MaterialNo, f.GramsMilli) {
				fit = false
				break
			}
		}
		if !fit || !acc.add(materialNo, milli) {
			return nil, fmt.Errorf("%w: 物料 %q 的数量超出范围：本次投料后累计实投将超过上限 %s 克",
				ErrInvalidInput, materialNo, maxGramsMilli)
		}

		seq := len(b.Feedings) + 1
		rec := feedingRecord{
			Seq:        seq,
			MaterialNo: materialNo,
			GramsMilli: milli,
			Time:       t,
			Registrar:  registrar,
		}
		view := FeedingView{
			Seq:        seq,
			MaterialNo: materialNo,
			Grams:      milli.String(),
			Time:       t,
			Registrar:  registrar,
		}
		raw, err := json.Marshal(view)
		if err != nil {
			return nil, err
		}
		b.Feedings = append(b.Feedings, rec)
		return raw, nil
	}, &out)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// GetBatch 按批次编号查询，返回未找到（ErrNotFound）时表示批次不存在。
// 返回内容包含所用配方版本、计划份数、状态、全部投料（登记顺序），
// 以及按物料逐项的应投量、累计实投量和差额；无投料的物料也会列出。
// 返回的视图是台账数据的副本，调用方修改不会影响台账。
func (s *Store) GetBatch(batchNo string) (*BatchView, error) {
	var out *BatchView
	err := s.read(func(st *persistedState) error {
		b := findBatch(st, batchNo)
		if b == nil {
			return fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
		}
		r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
		if r == nil {
			return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 不存在",
				ErrCorruptData, batchNo, b.RecipeNo, b.RecipeVersion)
		}
		view, err := buildBatchView(b, r)
		if err != nil {
			return err
		}
		out = view
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

package release

import "fmt"

// plannedMaterial 是数量核对规则对配方中一种物料的应投依据：
// 物料编号及其在当前计划份数下的应投量（千分之一克）。
type plannedMaterial struct {
	materialNo    string
	requiredGrams gramsMilli
}

// planRequirements 是批次“应投量依据”的唯一实现：给定批次采用的配方
// 版本 r 与最终采用的计划份数 portions，按配方中的物料顺序逐项计算
// 每份克数 × 计划份数，返回每种物料的应投量。
//
// 批次查询、关闭结果核对所需的完整数量核对（再加累计实投与差额）统一由
// reconcileMaterials 在本函数结果上继续计算；只需要应投依据的输入校验
// （创建批次、调整草稿）与读取校验（已保存批次的份数/应投量合法性）直接
// 调用本函数：
//   - 份数必须为正整数。份数的输入语义由各入口自行处理——创建要求正整数，
//     调整草稿时传 0 表示沿用当前份数（走到这里的必是最终正份数），读取
//     已保存批次时份数非正属于数据损坏；本函数只接受已确定的最终份数；
//   - 结果必须能精确表示到千分之一克：每份克数本身已是千分之一克的整数倍，
//     整数相乘不引入更小单位，不舍入、不截断；
//   - 每种物料分别以 maxGramsMilli（9223372036854775.807 克）为上限：
//     只乘该物料自己的每份克数与份数，不与同批次其他物料的应投量相加，
//     恰好等于上限合法，超过即返回错误。错误信息指出相关物料、配方编号、
//     版本与份数；调用方再按各自场景包装错误分类（提交时为
//     ErrInvalidInput，读取已保存批次时为 ErrCorruptData 并补充批次编号）。
//
// 不能改用同编号配方的其他版本：物料列表与每份克数一律取调用方给定的 r，
// 即批次实际绑定（或本次提交最终选定）的版本。
func planRequirements(r *recipeRecord, portions int) ([]plannedMaterial, error) {
	out := make([]plannedMaterial, 0, len(r.Materials))
	for _, m := range r.Materials {
		required, err := multiplyPortions(m.GramsMilli, portions)
		if err != nil {
			return nil, fmt.Errorf("物料 %q 按配方 %q 版本 %q 以 %d 份计算的应投量不合法: %v",
				m.MaterialNo, r.RecipeNo, r.Version, portions, err)
		}
		out = append(out, plannedMaterial{materialNo: m.MaterialNo, requiredGrams: required})
	}
	return out, nil
}

// materialQuantities 是批次中一种物料的完整数量核对结果（千分之一克）：
// 应投量、累计实投量与实投减应投的差额。差额可以为负；物料之间不互相
// 抵消，多种物料的差额相加为零也不代表数量吻合。
type materialQuantities struct {
	materialNo string
	required   gramsMilli
	actual     gramsMilli
	difference gramsMilli
}

// reconcileMaterials 是“批次逐物料数量核对”的唯一实现：给定批次实际
// 绑定的配方版本 r、计划份数 portions 与该批次的全部投料 feedings，
// 按 r 的物料顺序逐项算出每种物料的应投量、累计实投量与差额，每种物料
// 恰有一项，无投料的物料也不消失（实投为零、差额为负属正常结果）。
//
// 批次查询（GetBatch 等经由 buildBatchView）与读取已保存关闭结果时的
// 数量核对（validateCloseBatchRequest）一律调用本函数，对同一批次只
// 可能得到同一份数量依据，维护数量规则时不再有两处需要同步：
//   - 应投量统一由 planRequirements 按 r × portions 计算，千分之一克
//     精度与逐物料 maxGramsMilli 上限、份数必须为正等规则继续生效；
//   - 实投量只累计 feedings 中该物料自己的投料：用与追加投料、读取
//     校验相同的 feedingAccumulator 按物料分别累计，其他物料的投料
//     不参与、不互相抵消，逐物料累计上限同为 maxGramsMilli，恰好
//     达到上限合法，各种物料相加不作为超限依据；
//   - 差额 = 实投 - 应投，逐物料独立计算并保留正负号。
//
// 依据版本与份数一律取调用方给定值：查询用批次实际绑定的版本与当前
// 计划份数；关闭结果核对用原请求所指已关闭批次记录的版本与份数，不能
// 用同编号配方的其他版本或别的批次记录顶替。
func reconcileMaterials(r *recipeRecord, portions int, feedings []feedingRecord) ([]materialQuantities, error) {
	required, err := planRequirements(r, portions)
	if err != nil {
		return nil, err
	}
	// 累计规则与追加投料、validateFeedings 读取校验共用同一个累加器：
	// 只按物料分别累计该批次自己的投料，逐物料判断上限，不做物料间相加。
	acc := newFeedingAccumulator()
	for _, f := range feedings {
		if !acc.add(f.MaterialNo, f.GramsMilli) {
			return nil, fmt.Errorf("物料 %q 的累计实投超出可表示范围", f.MaterialNo)
		}
	}
	out := make([]materialQuantities, 0, len(required))
	for _, item := range required {
		actual := acc.total(item.materialNo)
		out = append(out, materialQuantities{
			materialNo: item.materialNo,
			required:   item.requiredGrams,
			actual:     actual,
			// 实投与应投都在 [0, maxGramsMilli] 内，差值落在 int64 范围内，
			// 不会回绕；欠投为负、超投为正，逐物料保留真实正负值。
			difference: actual - item.requiredGrams,
		})
	}
	return out, nil
}

// compareMaterialQuantities 是“已保存批次结果逐物料数量核对”的唯一比较
// 实现：mats 是保存结果里按物料列出的数量核对项，expected 是按该结果
// 各自依据经 reconcileMaterials 算出的数量核对（按依据版本的物料顺序
// 排列）。无投料快照结果（创建、草稿调整、开始执行：expected 的实投为
// 零、差额为应投量负值）与已关闭批次结果（expected 含全部实际投料的
// 累计）共用这里，差异只在调用方传入什么依据，本函数不关心依据从何而来。
//
// 核对规则：
//   - mats 必须与 expected 项数一致且每项物料编号按位置一致：项数不一致，
//     或某一项物料编号对不上（漏掉物料、重复物料、调换排列顺序或混入其他
//     版本的物料）都拒绝——总差额为零或原始投料完整都不能抵消这些问题；
//   - 每项的应投量、实投量、差额都必须与依据逐项相符：即使原始投料全部
//     正确，只改坏核对差额也属于损坏，不能用重新计算的正确值覆盖损坏结果
//     后继续使用（如何响应损坏由调用方决定，本函数只返回错误）；
//   - 数量按精确数值核对而非字符串写法：克数统一经 parseSignedGrams 解析
//     后比较，1 与 1.000、0 与 0.000、-1 与 -1.000 是同一数量，不因显示
//     写法不同误判；无法解析的写法本身就是损坏。这只放宽读取核对的写法
//     差异，请求内容的幂等匹配仍由写入路径按原文比较，不在本函数处理。
//
// 本函数只负责数量规则本身，返回的错误不带错误分类，且尽量指出问题物料
// 与数量原因（项数不符时没有具体物料可指）；调用方再按各自场景用
// ErrCorruptData 包装，并补充操作类别、请求编号与批次编号。
func compareMaterialQuantities(mats []MaterialRequirement, expected []materialQuantities) error {
	if len(mats) != len(expected) {
		return fmt.Errorf("保存结果的物料核对项数 %d 与数量依据的物料项数 %d 不一致，不能漏掉物料、重复物料或改变排列顺序",
			len(mats), len(expected))
	}
	for i, item := range expected {
		got := mats[i]
		if got.MaterialNo != item.materialNo {
			return fmt.Errorf("保存结果第 %d 项核对物料 %q 与数量依据的物料 %q 不一致（物料遗漏、重复、调换顺序或混入了其他版本的物料）",
				i+1, got.MaterialNo, item.materialNo)
		}
		for _, check := range []struct {
			name string
			raw  string
			want gramsMilli
		}{
			{"应投量", got.RequiredGrams, item.required},
			{"实投量", got.ActualGrams, item.actual},
			{"差额", got.DifferenceGrams, item.difference},
		} {
			v, err := parseSignedGrams(check.raw)
			if err != nil {
				return fmt.Errorf("保存结果物料 %q 的%s %q 无法解析为合法克数",
					item.materialNo, check.name, check.raw)
			}
			if v != check.want {
				return fmt.Errorf("保存结果物料 %q 的%s %s 与数量依据应有的值 %s 不一致",
					item.materialNo, check.name, check.raw, check.want)
			}
		}
	}
	return nil
}

// validateUnfedRequirements 核对“无投料批次快照”结果（创建批次、草稿调整
// 与开始执行三类已保存成功请求在读取台账时共用）的逐物料数量：这些结果
// 都是当时尚无投料的快照，数量依据即按 r × portions 计算、实投为零、
// 差额为应投量负值的核对——直接以空投料列表调用 reconcileMaterials 得到，
// 再与保存结果逐项比较。依据的选取仍由各调用方按自己的历史判断方式决定
// （创建用原请求选定的版本与份数；草稿调整用那次结果实际采用的版本与
// 份数，含沿用值；开始执行用批次开始时最终固定的版本与份数），本函数不
// 关心依据从何而来。项数/顺序、零实投、负差额、精确克数、精度与上限等
// 全部规则统一由 reconcileMaterials 与 compareMaterialQuantities 实现，
// 与关闭结果的核对共用同一处，不再单独维护一份。
func validateUnfedRequirements(mats []MaterialRequirement, r *recipeRecord, portions int) error {
	expected, err := reconcileMaterials(r, portions, nil)
	if err != nil {
		return err
	}
	return compareMaterialQuantities(mats, expected)
}

package release

import (
	"encoding/json"
	"errors"
	"time"
)

// BatchStatus 表示批次状态。
type BatchStatus string

const (
	// StatusDraft 草稿：可以调整计划份数或改选配方版本。
	StatusDraft BatchStatus = "draft"
	// StatusExecuting 执行中：份数与配方已固定，可追加投料。
	StatusExecuting BatchStatus = "executing"
	// StatusClosed 已关闭：确认已有投料，不可再追加或重新打开。
	StatusClosed BatchStatus = "closed"
)

// validBatchStatus 是已保存批次状态允许出现的全部取值，必须精确匹配。
// 读取台账时状态只能是这三个字符串之一：缺失、为空、null、其他字符串，
// 或大小写不同、前后多出空格的近似写法都不自动归入某个合法状态。
var validBatchStatus = map[BatchStatus]bool{
	StatusDraft:     true,
	StatusExecuting: true,
	StatusClosed:    true,
}

// isValidBatchStatus 判断已保存批次状态是否精确对应一个合法状态。
// 只做逐字符的精确匹配，不做大小写归一化或去空格："Draft"、" draft "
// 等写法与 "ready"、空字符串一样属于无法识别的状态。
func isValidBatchStatus(s BatchStatus) bool {
	return validBatchStatus[s]
}

// MaterialInput 是登记配方时的物料输入。
type MaterialInput struct {
	// MaterialNo 物料编号，同一配方版本内不可重复。
	MaterialNo string
	// Grams 生产一份该物料需要的克数，必须为正数且最多三位小数。
	Grams string
}

// MaterialView 是配方物料的查询视图。
type MaterialView struct {
	MaterialNo string
	Grams      string
}

// RecipeView 是配方版本的查询视图。
type RecipeView struct {
	RecipeNo  string
	Version   string
	Name      string
	Materials []MaterialView
}

// FeedingView 是一条投料记录的查询视图。
type FeedingView struct {
	Seq        int       // 投料登记顺序，从 1 开始
	MaterialNo string    // 物料编号（必然属于该批次绑定的配方版本）
	Grams      string    // 本次投料克数
	Time       time.Time // 投料时间（由调用方填写，不参与排序）
	Registrar  string    // 登记人
}

// MaterialRequirement 是按物料逐项列出的数量核对结果。
type MaterialRequirement struct {
	MaterialNo      string
	RequiredGrams   string // 应投量 = 每份克数 × 计划份数
	ActualGrams     string // 累计实投量（仅统计该物料的投料）
	DifferenceGrams string // 实投减应投（可能为负；物料之间不互相抵消）
}

// BatchView 是批次查询视图。
type BatchView struct {
	BatchNo         string
	RecipeNo        string
	RecipeVersion   string
	RecipeName      string
	PlannedPortions int
	Status          BatchStatus
	Feedings        []FeedingView         // 按成功登记的先后顺序排列
	Materials       []MaterialRequirement // 配方中每种物料一项，无投料也显示
}

// 导出的错误。调用方可以用 errors.Is 判定类别，
// 具体原因会通过 fmt.Errorf("%w: ...") 附带在错误信息中。
var (
	// ErrNotFound 查询的批次或配方版本不存在。
	ErrNotFound = errors.New("未找到")
	// ErrDuplicateBatch 批次编号已存在。
	ErrDuplicateBatch = errors.New("批次编号重复")
	// ErrRecipeExists 配方版本已登记，内容不可覆盖。
	ErrRecipeExists = errors.New("配方版本已存在，不可覆盖")
	// ErrInvalidInput 输入不合法（编号为空、克数非法、份数非正整数等）。
	ErrInvalidInput = errors.New("输入不合法")
	// ErrInvalidState 当前批次状态不允许该操作。
	ErrInvalidState = errors.New("当前状态不允许该操作")
	// ErrMaterialNotInRecipe 投料物料不属于该批次绑定的配方版本。
	ErrMaterialNotInRecipe = errors.New("物料不属于该批次的配方版本")
	// ErrRequestConflict 请求编号已被用于其他操作或不同内容。
	ErrRequestConflict = errors.New("请求编号冲突")
	// ErrCorruptData 台账数据已损坏或无法读取，不能当成空台账继续。
	ErrCorruptData = errors.New("台账数据损坏，无法读取")
)

// 内部持久化记录。

type materialRecord struct {
	MaterialNo string     `json:"materialNo"`
	GramsMilli gramsMilli `json:"gramsMilli"`
}

type recipeRecord struct {
	RecipeNo  string           `json:"recipeNo"`
	Version   string           `json:"version"`
	Name      string           `json:"name"`
	Materials []materialRecord `json:"materials"`
}

type feedingRecord struct {
	Seq        int        `json:"seq"`
	MaterialNo string     `json:"materialNo"`
	GramsMilli gramsMilli `json:"gramsMilli"`
	Time       time.Time  `json:"time"`
	Registrar  string     `json:"registrar"`
}

type batchRecord struct {
	BatchNo         string          `json:"batchNo"`
	RecipeNo        string          `json:"recipeNo"`
	RecipeVersion   string          `json:"recipeVersion"`
	PlannedPortions int             `json:"plannedPortions"`
	Status          BatchStatus     `json:"status"`
	Feedings        []feedingRecord `json:"feedings"`
}

type requestRecord struct {
	Op      string          `json:"op"`
	Payload string          `json:"payload"`
	Result  json.RawMessage `json:"result"`
}

type persistedState struct {
	Version  int                       `json:"version"`
	Recipes  []*recipeRecord           `json:"recipes"`
	Batches  []*batchRecord            `json:"batches"`
	Requests map[string]*requestRecord `json:"requests"`
}

package release

import (
	"fmt"
	"time"
)

// feedingContent 是读取台账时一份待核对的投料内容：物料编号、克数原文、
// 投料时间与登记人。两处读取核对都要判断这样的内容是否就是批次中的
// 某条实际投料：
//   - 已保存的成功投料请求：保存结果（FeedingView）必须对应原请求批次中
//     同序号的实际投料，同时还要符合原提交内容（addFeedingPayload）——
//     两个来源都先整理成本结构，再按同一套规则核对；
//   - 已保存的成功关闭请求：保存结果中的每条投料（FeedingView）必须按
//     登记顺序与批次确认的同位置实际投料一致。
//
// 两种场景的业务依据与错误说明各自保留在调用方（投料请求要符合原提交
// 内容、关闭结果要指出第几条投料），投料内容本身的判断标准统一由本
// 文件实现，不再分别维护。
type feedingContent struct {
	materialNo string
	grams      string
	time       time.Time
	registrar  string
}

// feedingViewContent 取出保存结果中一条投料视图的待核对内容。
func feedingViewContent(fv FeedingView) feedingContent {
	return feedingContent{
		materialNo: fv.MaterialNo,
		grams:      fv.Grams,
		time:       fv.Time,
		registrar:  fv.Registrar,
	}
}

// feedingPayloadContent 取出投料请求原提交内容的待核对内容。
func feedingPayloadContent(p addFeedingPayload) feedingContent {
	return feedingContent{
		materialNo: p.MaterialNo,
		grams:      p.Grams,
		time:       p.Time,
		registrar:  p.Registrar,
	}
}

// parsedFeedingContent 是克数已换算成千分之一克的投料内容，
// 可以直接与另一份已解析内容比较。
type parsedFeedingContent struct {
	materialNo string
	gramsMilli gramsMilli
	time       time.Time
	registrar  string
}

// parse 把克数原文换算成千分之一克，得到可比较的投料内容。换算规则与
// 登记投料时相同（parseGrams）：1 与 1.000 是同一数量。克数写法无法
// 解析时返回错误——“克数不合法”与“内容不符”是两种可区分的损坏原因，
// 这里只负责前者，由调用方按各自场景（保存结果还是原提交内容、第几条
// 投料）包装报告。
func (c feedingContent) parse() (parsedFeedingContent, error) {
	g, err := parseGrams(c.grams)
	if err != nil {
		return parsedFeedingContent{}, fmt.Errorf("克数 %q 不合法", c.grams)
	}
	return parsedFeedingContent{
		materialNo: c.materialNo,
		gramsMilli: g,
		time:       c.time,
		registrar:  c.registrar,
	}, nil
}

// feedingRecordContent 取出批次中一条实际投料记录的已解析内容：
// 记录中的克数本就以千分之一克保存，无需再解析。
func feedingRecordContent(rec feedingRecord) parsedFeedingContent {
	return parsedFeedingContent{
		materialNo: rec.MaterialNo,
		gramsMilli: rec.GramsMilli,
		time:       rec.Time,
		registrar:  rec.Registrar,
	}
}

// matches 是“两份投料内容是否表示同一次投料”的唯一判断：物料编号与
// 登记人精确匹配，克数比较实际数量（1 与 1.000 解析后相同），时间比较
// 同一时刻（不区分时区写法）。实际数量、时间或登记人不同即不表示同一
// 次投料——即使与其他记录的数量合计相同，也不能顶替。该判断只用于读取
// 核对；请求内容的幂等匹配仍由写入路径按提交原文比较（把 1.000 改成 1
// 再提交仍是 ErrRequestConflict），不经过这里。
func (c parsedFeedingContent) matches(other parsedFeedingContent) bool {
	return c.materialNo == other.materialNo &&
		c.gramsMilli == other.gramsMilli &&
		c.time.Equal(other.time) &&
		c.registrar == other.registrar
}

