283	// 保留两种拒绝行为的区分：
284	//   - 换一个未使用的请求编号开始已经执行（或已关闭）的批次 → ErrInvalidState；
285	//   - 把首次成功的请求编号用于开始另一个仍为草稿的批次 → ErrRequestConflict
286	//     （操作相同但批次编号不同）。
287	// 被拒绝后，另一个批次仍是草稿，原批次的状态与投料也不受影响；
288	// 原成功请求仍可取得首次结果。
289	func TestStartBatchReplayRejections(t *testing.T) {
290		s := openTestStore(t)
291		registerReplayRecipes(t, s)
292		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 5); err != nil {
293			t.Fatalf("创建 B1 失败: %v", err)
294		}
295		if _, err := s.UpdateDraftBatch("u-final", "B1", "R1", "v2", 3); err != nil {
296			t.Fatalf("调整 B1 失败: %v", err)
297		}
298		// 另一个仍为草稿的批次 B2，沿用 R1/v1、7 份。
299		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 7); err != nil {
300			t.Fatalf("创建 B2 失败: %v", err)
301		}
302	
303		first, err := s.StartBatch("start-b1", "B1")
304		if err != nil {
305			t.Fatalf("首次开始 B1 应成功: %v", err)
306		}
307		checkFirstStartView(t, first)
308	
309		// 执行中：新请求编号再次开始 B1 → ErrInvalidState（不会被当成幂等重放）。
310		if _, err := s.StartBatch("start-fresh-executing", "B1"); !errors.Is(err, ErrInvalidState) {
311			t.Fatalf("新编号开始执行中的批次应返回 ErrInvalidState，得到 %v", err)
312		}
313		// 首次成功的编号用于开始另一个草稿批次 B2 → ErrRequestConflict。
314		if _, err := s.StartBatch("start-b1", "B2"); !errors.Is(err, ErrRequestConflict) {
315			t.Fatalf("同编号开始另一批次应返回 ErrRequestConflict，得到 %v", err)
316		}
317	
318		// 投料并关闭 B1。
319		base := replayFeedTime()
320		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", base, "张三"); err != nil {
321			t.Fatalf("投料 f1 失败: %v", err)
322		}
323		if _, err := s.AddFeeding("f2", "B1", "M4", "2", base.Add(time.Hour), "李四"); err != nil {
324			t.Fatalf("投料 f2 失败: %v", err)
325		}
326		if _, err := s.AddFeeding("f3", "B1", "M1", "50", base.Add(2*time.Hour), "张三"); err != nil {
327			t.Fatalf("投料 f3 失败: %v", err)
328		}
329		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
330			t.Fatalf("关闭 B1 失败: %v", err)
331		}
332	
333		// 已关闭：新编号开始 B1 → ErrInvalidState，绝不能改回执行中。
334		if _, err := s.StartBatch("start-fresh-closed", "B1"); !errors.Is(err, ErrInvalidState) {
335			t.Fatalf("新编号开始已关闭批次应返回 ErrInvalidState，得到 %v", err)
336		}
337		// 原成功编号用于 B2 仍是冲突。
338		if _, err := s.StartBatch("start-b1", "B2"); !errors.Is(err, ErrRequestConflict) {
339			t.Fatalf("关闭后同编号开始另一批次仍应返回 ErrRequestConflict，得到 %v", err)
340		}
341	
342		// 被拒绝后 B2 仍是原样草稿：R1/v1、7 份、无投料、零实投。
343		b2 := mustGetBatch(t, s, "B2")
344		if b2.Status != StatusDraft || b2.RecipeNo != "R1" || b2.RecipeVersion != "v1" ||
345			b2.RecipeName != "配方初版" || b2.PlannedPortions != 7 {
346			t.Fatalf("被拒绝后 B2 应仍是 R1/v1、7 份的草稿，得到 %+v", b2)
347		}
348		if len(b2.Feedings) != 0 {
349			t.Fatalf("B2 不应出现投料，得到 %d 条: %+v", len(b2.Feedings), b2.Feedings)
350		}
351		b2Mats := materialsMap(b2)
352		if len(b2Mats) != 2 {
353			t.Fatalf("B2 应仍是 v1 的 M1、M2 两种物料，得到 %d 项: %+v", len(b2Mats), b2.Materials)
354		}
355		checkRequirement(t, b2Mats, "M1", "0.875", "0", "-0.875") // 0.125 × 7
356		checkRequirement(t, b2Mats, "M2", "3.5", "0", "-3.5")     // 0.5 × 7
357	
358		// B1 仍是已关闭状态，投料与数量核对不变。
359		checkClosedCurrent(t, mustGetBatch(t, s, "B1"))
360	
361		// 原成功请求仍可取得首次开始时的原始结果。
362		replay, err := s.StartBatch("start-b1", "B1")
363		if err != nil {
364			t.Fatalf("拒绝后原成功请求仍应可重放: %v", err)
365		}
366		checkFirstStartView(t, replay)
367	}
368	
369	// mustGetBatch 查询批次，失败时立即终止测试。
370	func mustGetBatch(t *testing.T, s *Store, batchNo string) *BatchView {
371		t.Helper()
372		v, err := s.GetBatch(batchNo)
373		if err != nil {
374			t.Fatalf("查询批次 %q 失败: %v", batchNo, err)
375		}
376		return v
377	}
378

