23	// setupStartRequestLedger 在 dir 建立一份正常台账：
24	//   - B1（已关闭）：创建时用 R1/v1、5 份，草稿调整为 R1/v2、3 份后由
25	//     start-b1 开始，随后登记两条投料（f1、f2）并由 close-b1 关闭——
26	//     其保存的开始结果必须是首次开始时的内容（R1/v2、3 份、执行中、
27	//     空投料），不能混入后来的投料与关闭现状；
28	//   - B2（执行中）：与 B1 相同的最终配方与份数，start-b2 开始，无投料——
29	//     其保存结果与 B1 的首次开始结果仅批次编号不同，用于验证另一批次的
30	//     结果不能顶替；
31	//   - B3（执行中）：R1/v1、2 份，无投料的正常批次，用于验证损坏的开始
32	//     请求不能被“本次访问的是另一个正常批次”绕过。
33	//
34	// 返回落盘后的台账文件内容，供各用例改坏后重写。
35	func setupStartRequestLedger(t *testing.T, dir string) []byte {
36		t.Helper()
37		s, err := Open(dir)
38		if err != nil {
39			t.Fatalf("Open 失败: %v", err)
