41		registerReplayRecipes(t, s) // R1/v1：M1=0.125、M2=0.5；R1/v2：M1=250、M4=2
42		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 5); err != nil {
43			t.Fatal(err)
44		}
45		if _, err := s.UpdateDraftBatch("u-final", "B1", "R1", "v2", 3); err != nil {
46			t.Fatal(err)
47		}
48		if _, err := s.StartBatch("start-b1", "B1"); err != nil {
49			t.Fatal(err)
50		}
51		base := replayFeedTime()
52		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", base, "张三"); err != nil {
53			t.Fatal(err)
54		}
55		if _, err := s.AddFeeding("f2", "B1", "M4", "2", base, "李四"); err != nil {
56			t.Fatal(err)
57		}
58		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
59			t.Fatal(err)
60		}
61		// B2：最终配方与份数和 B1 相同，仅批次编号与请求编号不同。
62		if _, err := s.CreateBatch("b2", "B2", "R1", "v2", 3); err != nil {
63			t.Fatal(err)
64		}
65		if _, err := s.StartBatch("start-b2", "B2"); err != nil {
66			t.Fatal(err)
67		}
