336	// 正常写法差异不能误判为损坏：保存结果的应投量写成 750.000、实投量写成
337	// 0.000、差额写成 -750.000，与首次开始时的数量是同一数值；合法的零实投与
338	// 负差额不是损坏。台账应正常打开，重放仍返回保存的写法。
339	func TestOpenAcceptsStartRequestResultFormatVariants(t *testing.T) {
