345		}
346		if !bytes.Equal(got, bad) {
347			t.Fatalf("拒绝打开不应改动台账文件")
348		}
349	}
350	
351	// 正常写法差异不能误判为损坏：保存结果的克数写成 0.100、应投量写成 0.300、
352	// 差额写成 -0.100，与批次记录是同一数量；投料时间表示同一时刻、仅时区写法
353	// 不同也合法。台账应正常打开，重放仍返回第一次关闭时的完整结果。
354	func TestOpenAcceptsCloseRequestResultFormatVariants(t *testing.T) {
355		dir := t.TempDir()
356		good := setupCloseRequestLedger(t, dir)
357	
358		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
359			return mutatedCloseView(t, good, func(v *BatchView) {
360				v.Feedings[0].Grams = "0.100" // 与 0.1 是同一数量
361				v.Feedings[0].Time = v.Feedings[0].Time.In(time.FixedZone("UTC+8", 8*3600))
362				v.Materials[0].RequiredGrams = "0.300"
363				v.Materials[1].ActualGrams = "0.500"
364				v.Materials[1].DifferenceGrams = "-0.100"
365			})
366		})
367		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
368			t.Fatal(err)
369		}
370	
371		s, err := Open(dir)
372		if err != nil {
373			t.Fatalf("写法差异不应判为损坏: %v", err)
374		}
375		defer s.Close()
376	
377		// 重放取回保存的结果原文：第 1 条投料的克数保持 0.100 写法、时间保持
378		// UTC+8 写法，但与批次实际投料是同一数量、同一时刻。
379		replay, err := s.CloseBatch("close-b1", "B1")
380		if err != nil {
381			t.Fatalf("重放关闭请求应成功: %v", err)
382		}
383		want := wantCloseFeedings()
384		if replay.Feedings[0].Grams != "0.100" {
385			t.Fatalf("重放应返回保存的克数写法 0.100，得到 %q", replay.Feedings[0].Grams)
386		}
387		if !replay.Feedings[0].Time.Equal(want[0].Time) {
388			t.Fatalf("重放投料时间应与原投料为同一时刻，得到 %v", replay.Feedings[0].Time)
389		}
390		if replay.Materials[0].RequiredGrams != "0.300" || replay.Materials[1].DifferenceGrams != "-0.100" {
391			t.Fatalf("重放应返回保存的核对项写法，得到 %+v", replay.Materials)
392		}
393		// 按批次查询得到系统规范化写法的视图，内容与首次关闭一致。
394		checkClosedB1View(t, mustGetBatch(t, s, "B1"))
395	}
396	
397	// 关闭只确认已有投料、不要求数量吻合：没有投料、实投为零、差额为负的批次
398	// 关闭后，保存结果如实记录零实投与负差额，不能被当成损坏。重新打开台账
399	// 应正常，重放仍返回第一次关闭时的完整结果。
400	func TestCloseRequestResultAllowsZeroActualAndNegativeDifference(t *testing.T) {
401		dir := t.TempDir()
402		s, err := Open(dir)
403		if err != nil {
404			t.Fatalf("Open 失败: %v", err)
405		}
406		registerCloseRecipe(t, s)
407		if _, err := s.CreateBatch("b9", "B9", "RC", "v1", 3); err != nil {
408			t.Fatal(err)
409		}
410		if _, err := s.StartBatch("start-b9", "B9"); err != nil {
411			t.Fatal(err)
412		}
413		first, err := s.CloseBatch("close-b9", "B9")
414		if err != nil {
415			t.Fatalf("无投料的执行中批次应可关闭: %v", err)
416		}
417		checkZeroClosed := func(v *BatchView) {
418			t.Helper()
419			if v.Status != StatusClosed || len(v.Feedings) != 0 {
420				t.Fatalf("应为无投料的已关闭批次，得到 %+v", v)
421			}
422			mats := materialsMap(v)
423			checkRequirement(t, mats, "M1", "0.3", "0", "-0.3")
424			checkRequirement(t, mats, "M2", "0.6", "0", "-0.6")
425		}
426		checkZeroClosed(first)
427		if err := s.Close(); err != nil {
428			t.Fatal(err)
429		}
430	
431		s2, err := Open(dir)
432		if err != nil {
433			t.Fatalf("零实投与负差额不应判为损坏: %v", err)
434		}
435		defer s2.Close()
436		replay, err := s2.CloseBatch("close-b9", "B9")
437		if err != nil {
438			t.Fatalf("重放关闭请求应成功: %v", err)
439		}
440		checkZeroClosed(replay)
441		checkZeroClosed(mustGetBatch(t, s2, "B9"))
442	}
443	
444	// 台账正常打开后，保存内容中的关闭请求结果被改坏：下一次查询或写入必须
445	// 返回 ErrCorruptData——即使本次访问的是另一个正常批次，也不能忽略损坏的
446	// 关闭请求；被拒绝的重放不得返回损坏的保存结果，被拒绝的写入不留业务变化、
447	// 不占用请求编号，原台账内容不变。恢复后原成功请求仍可幂等重放，被拒绝过
448	// 的请求编号可以正常使用。
449	func TestCloseRequestResultCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
450		dir := t.TempDir()
451		good := setupCloseRequestLedger(t, dir)
452	
453		s, err := Open(dir)
454		if err != nil {
455			t.Fatal(err)
456		}
457		defer s.Close()
458	
459		// 打开后把 close-b1 的保存结果改坏为空对象（其余记录保持完整）。
460		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
461			return json.RawMessage(`{}`)
462		})
463		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
464			t.Fatal(err)
465		}
466	
467		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容。
468		for _, batchNo := range []string{"B1", "B3"} {
469			if v, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
470				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
471			} else if v != nil {
472				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
473			}
474		}
475		// 用原编号、原内容重放损坏的关闭请求：不得把损坏的保存结果当成成功
476		// 结果返回，必须报损坏。
477		if _, err := s.CloseBatch("close-b1", "B1"); !errors.Is(err, ErrCorruptData) {
478			t.Fatalf("重放损坏的关闭请求应返回 ErrCorruptData，得到 %v", err)
479		}
480		// 对正常批次的新写入同样不能绕过。
481		if _, err := s.CloseBatch("close-b3", "B3"); !errors.Is(err, ErrCorruptData) {
482			t.Fatalf("损坏台账上关闭正常批次应返回 ErrCorruptData，得到 %v", err)
483		}
484	
485		// 被拒绝的访问不改动文件、不占用请求编号。
486		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
487		if err != nil {
488			t.Fatal(err)
489		}
490		if !bytes.Equal(after, bad) {
491			t.Fatalf("被拒绝的访问不应改动台账文件")
492		}
493		if bytes.Contains(after, []byte("close-b3")) {
494			t.Fatalf("被拒绝的写入不应留下请求记录")
495		}
496	
497		// 恢复后：原成功请求仍取回第一次关闭的完整结果，被拒绝过的请求编号
498		// 可以正常使用。
499		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
500			t.Fatal(err)
501		}
502		replay, err := s.CloseBatch("close-b1", "B1")
503		if err != nil {
504			t.Fatalf("恢复后重放原成功请求失败: %v", err)
505		}
506		checkClosedB1View(t, replay)
507		closed, err := s.CloseBatch("close-b3", "B3")
508		if err != nil {
509			t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
510		}
511		if closed.Status != StatusClosed || closed.BatchNo != "B3" {
512			t.Fatalf("B3 应被正常关闭，得到 %+v", closed)
513		}
514	}
515

