// startBatchRequestCheck 是已保存开始执行请求的共有核对配置：原批次当前
// 为执行中或已关闭即可，配方与份数表述为“批次开始时确定”。
var startBatchRequestCheck = statusTransitionRequest{
	opLabel:           "开始执行请求",
	resultLabel:       "开始结果",
	successLabel:      "开始成功",
	allowedStatusDesc: "不是执行中或已关闭",
	recipeBasisDesc:   "批次开始时确定的配方",
