		return nil, nil, nil, fmt.Errorf("%w: %s %q 对应的批次 %q 不存在，保存的%s不能单独作为%s的依据",
			ErrCorruptData, cfg.opLabel, reqNo, batchNo, cfg.resultLabel, cfg.successLabel)
	}
	// 当前状态必须在允许范围内：开始结果允许执行中或已关闭（开始后状态
	// 只前进，被改回草稿即不一致）；关闭结果只允许已关闭。
