	if err := json.Unmarshal(req.Result, &result); err != nil {
		return fmt.Errorf("%w: 开始执行请求 %q（批次 %q）保存的开始结果无法解析为完整批次结果",
			ErrCorruptData, reqNo, batchNo)
	}
