	if result.BatchNo == "" {
		return fmt.Errorf("%w: 开始执行请求 %q（批次 %q）保存的开始结果缺失或不完整",
			ErrCorruptData, reqNo, batchNo)
	}
	// 原请求所指的批次必须存在：批次没有了，保存的结果不能单独作为开始
	// 成功的依据。
